                };
                (ClusterState {
                    controller_and_externals: s.controller_and_externals.insert(controller_id, controller_and_external_state_prime),
                    ..s
                }, ())
            },
        }
    }

    pub open spec fn disable_crash(self) -> Action<ClusterState, int, ()> {
